mapper.select:
SELECT id, email, nickname, profile, created_at, status
FROM member
WHERE id = #{memberId}

mapper.update:
UPDATE member
SET email = #{email},
    nickname = #{nickname},
    profile = #{profile},
    status = #{status}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM member
WHERE nickname = #{nickname}
  AND id != #{memberId}
  AND status = 'Y'

mapper.update:
UPDATE member
SET nickname = #{nickname}
WHERE id = #{memberId}
  AND status = 'Y'

UPDATE member
SET profile = #{profile}
WHERE id = #{memberId}
  AND status = 'Y'

UPDATE member
SET status = #{status}
WHERE id = #{memberId}
  AND status = 'Y'
